import{_ as t}from"./chunks/qgc_setup_power_px4.C_5Q_Dnv.js";import{_ as a,c as o,al as r,o as i}from"./chunks/framework.DCERqlYr.js";const b=JSON.parse('{"title":"电池和电源模块设置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/config/battery.md","filePath":"zh/config/battery.md"}'),s={name:"zh/config/battery.md"};function l(n,e,c,d,h,u){return i(),o("div",null,e[0]||(e[0]=[r('<h1 id="电池和电源模块设置" tabindex="-1">电池和电源模块设置 <a class="header-anchor" href="#电池和电源模块设置" aria-label="Permalink to &quot;电池和电源模块设置&quot;">​</a></h1><p>该主题解释了如何进行电源设置</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>These instructions require that the vehicle has a <a href="./../power_module/">Power Module (PM)</a>, or other hardware that can measure the battery voltage and (optionally) the current.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This tuning is not needed for <a href="./../smart_batteries/">Smart/MAVLink Batteries</a>: batteries that can supply a reliable indication of remaining charge.</p></div><h2 id="综述" tabindex="-1">综述 <a class="header-anchor" href="#综述" aria-label="Permalink to &quot;综述&quot;">​</a></h2><p>Battery Estimation Tuning uses the measured voltage and current (if available) to estimate the remaining battery capacity. This is important because it allows PX4 to take action when the vehicle is close to running out of power and crashing (and also to prevent battery damage due to deep-discharge).</p><p>PX4 提供了许多（逐渐变得更有效）可用于估计容量的方法：</p><ol><li><a href="#basic_settings">Basic Battery Settings</a> (default): raw measured voltage is compared to the range between &quot;empty&quot; and &quot;full&quot; voltages. 这样的估计较为粗略，因为测量的电压（及其相应的容量）将在负载下产生波动。</li><li><a href="#load_compensation">Voltage-based Estimation with Load Compensation</a>: Counteracts the effects of loading on the capacity calculation.</li><li><a href="#current_integration">Voltage-based Estimation with Current Integration</a>: Fuses the load-compensated voltage-based estimate for the available capacity with a current-based estimate of the charge that has been consumed. 这样的容量估计相当于智能电池的容量估计。</li></ol><p>后面的方法建立在前面的方法之上。 您使用的方法将取决于机体的电源模块是否可以测量电流。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The instructions below refer to battery 1 calibration parameters: <code>BAT1_*</code>. Other batteries use the <code>BATx_*</code> parameters, where <code>x</code> is the battery number. All battery calibration parameters <a href="./../advanced_config/parameter_reference.html#battery-calibration">are listed here</a>.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>In addition to PX4 configuration discussed here, you should ensure that the ESC&#39;s low voltage cutoff is either disabled or set below the expected minimum voltage. 这确保了电池故障保护行为由 PX4 管理，并且当电池仍有电量时，ESC 不会断电（根据您选择的“空电池”设置）。</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><a href="./../power_systems/battery_chemistry.html">Battery Chemistry Overview</a> explains the difference between the main battery types, and how that impacts the battery settings.</p></div><h2 id="basic_settings" tabindex="-1">Basic Battery Settings (default) <a class="header-anchor" href="#basic_settings" aria-label="Permalink to &quot;Basic Battery Settings (default) {#basic_settings}&quot;">​</a></h2><p>基本电池设置将PX4配置为使用默认方法进行容量估算。 此方法将测得的原始电池电压与“空”和“满”电芯的电池电压范围进行比较（按芯数量缩放）。</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This approach results in relatively coarse estimations due to fluctuations in the estimated charge as the measured voltage changes under load.</p></div><p>配置电池1的基本参数：</p><ol><li>Start <em>QGroundControl</em> and connect the vehicle.</li><li>Select <strong>&quot;Q&quot; icon &gt; Vehicle Setup &gt; Power</strong> (sidebar) to open <em>Power Setup</em>.</li></ol><p>You are presented with the basic settings that characterize the battery. The sections below explain what values to set for each field.</p><p><img src="'+t+'" alt="QGC Power Setup"></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>At time of writing <em>QGroundControl</em> only allows you to set values for battery 1 in this view. For vehicles with multiple batteries you&#39;ll need to directly <a href="./../advanced_config/parameters.html">set the parameters</a> for battery 2 (<code>BAT2_*</code>), as described in the following sections.</p></div><h3 id="电池芯数-串联" tabindex="-1">电池芯数（串联） <a class="header-anchor" href="#电池芯数-串联" aria-label="Permalink to &quot;电池芯数（串联）&quot;">​</a></h3><p>This sets the number of cells connected in series in the battery. Typically this will be written on the battery as a number followed by &quot;S&quot; (e.g &quot;3S&quot;, &quot;5S&quot;).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The voltage across a single galvanic battery cell is dependent on the <a href="./../power_systems/battery_chemistry.html">chemical properties of the battery type</a>. Lithium-Polymer (LiPo) batteries and Lithium-Ion batteries both have the same <em>nominal</em> cell voltage of 3.7V. In order to achieve higher voltages (which will more efficiently power a vehicle), multiple cells are connected in <em>series</em>. The battery voltage at the terminals is then a multiple of the cell voltage.</p></div><p>If the number of cells is not supplied you can calculate it by dividing the battery voltage by the nominal voltage for a single cell. The table below shows the voltage-to-cell relationship for these batteries:</p><table tabindex="0"><thead><tr><th>Cells</th><th>LiPo (V)</th><th>LiIon (V)</th></tr></thead><tbody><tr><td>1S</td><td>3.7</td><td>3.7</td></tr><tr><td>2S</td><td>7.4</td><td>7.4</td></tr><tr><td>3S</td><td>11.1</td><td>11.1</td></tr><tr><td>4S</td><td>14.8</td><td>14.8</td></tr><tr><td>5S</td><td>18.5</td><td>18.5</td></tr><tr><td>6S</td><td>22.2</td><td>22.2</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This setting corresponds to <a href="./../advanced_config/parameters.html">parameters</a>: <a href="./../advanced_config/parameter_reference.html#BAT1_N_CELLS">BAT1_N_CELLS</a> and <a href="./../advanced_config/parameter_reference.html#BAT2_N_CELLS">BAT2_N_CELLS</a>.</p></div><h3 id="full-voltage-per-cell" tabindex="-1">Full Voltage (per cell) <a class="header-anchor" href="#full-voltage-per-cell" aria-label="Permalink to &quot;Full Voltage (per cell)&quot;">​</a></h3><p>This sets the <em>nominal</em> maximum voltage of each cell (the lowest voltage at which the cell will be considered &quot;full&quot;).</p><p>The value should be set slightly lower that the nominal maximum cell voltage for the battery, but not so low that the estimated capacity is still 100% after a few minutes of flight.</p><p>Appropriate values to use are:</p><ul><li><strong>LiPo:</strong> 4.05V (default in <em>QGroundControl</em>)</li><li><strong>LiIon:</strong> 4.05V</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The voltage of a full battery may drop a small amount over time after charging. Setting a slightly-lower than maximum value compensates for this drop.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This setting corresponds to <a href="./../advanced_config/parameters.html">parameters</a>: <a href="./../advanced_config/parameter_reference.html#BAT1_V_CHARGED">BAT1_V_CHARGED</a> and <a href="./../advanced_config/parameter_reference.html#BAT2_V_CHARGED">BAT2_V_CHARGED</a>.</p></div><h3 id="空电电压-每个电芯" tabindex="-1">空电电压（每个电芯） <a class="header-anchor" href="#空电电压-每个电芯" aria-label="Permalink to &quot;空电电压（每个电芯）&quot;">​</a></h3><p>This sets the nominal minimum safe voltage of each cell (using below this voltage may damage the battery).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>There is no single value at which a battery is said to be empty. If you choose a value that is too low the battery may be damaged due to deep discharge (and/or the vehicle may crash). If you choose a value that is too high you may unnecessarily curtail your flight.</p></div><p>A rule of thumb for minimum per-cell voltages:</p><table tabindex="0"><thead><tr><th>Level</th><th>LiPo (V)</th><th>LiIon (V)</th></tr></thead><tbody><tr><td>Conservative (voltage under no-load)</td><td>3.7</td><td>3</td></tr><tr><td>&quot;Real&quot; minimum (voltage under load/while flying)</td><td>3.5</td><td>2.7</td></tr><tr><td>Damage battery (voltage under load)</td><td>3.0</td><td>2.5</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Below the conservative range, the sooner you recharge the battery the better - it will last longer and lose capacity slower.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This setting corresponds to <a href="./../advanced_config/parameters.html">parameter</a>: <a href="./../advanced_config/parameter_reference.html#BAT1_V_EMPTY">BAT1_V_EMPTY</a> and <a href="./../advanced_config/parameter_reference.html#BAT2_V_EMPTY">BAT2_V_EMPTY</a>.</p></div><h3 id="voltage-divider" tabindex="-1">Voltage Divider <a class="header-anchor" href="#voltage-divider" aria-label="Permalink to &quot;Voltage Divider&quot;">​</a></h3><p>If you have a vehicle that measures voltage through a power module and the ADC of the flight controller then you should calibrate the measurements once per power module. To calibrate, the actual voltage from the battery is measured (using a multimeter) and compared to the value provided by the power module. This is used to calculate a &quot;voltage divider&quot; value, which can subsequently be used to scale the power module measurement to the correct value.</p><p>The easiest way to perform this calibration is by using <em>QGroundControl</em> and following the step-by-step guide on <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/setup_view/power.html" target="_blank" rel="noreferrer">Setup &gt; Power Setup</a> (QGroundControl User Guide).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This setting corresponds to parameters: <a href="./../advanced_config/parameter_reference.html#BAT1_V_DIV">BAT1_V_DIV</a> and <a href="./../advanced_config/parameter_reference.html#BAT2_V_DIV">BAT2_V_DIV</a>.</p></div><h3 id="current_divider" tabindex="-1">Amps per volt <a class="header-anchor" href="#current_divider" aria-label="Permalink to &quot;Amps per volt {#current_divider}&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This calibration is not needed if your power module does not provide current measurements.</p></div><p>Current measurements are used (by default) for <a href="#load_compensation">Load Compensation</a> and <a href="#current_integration">Current Integration</a> if provided by the power module. The amps per volt divider must be calibrated to ensure an accurate current measurement.</p><p>The easiest way to calibrate the dividers is by using <em>QGroundControl</em> and following the step-by-step guide on <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/setup_view/power.html" target="_blank" rel="noreferrer">Setup &gt; Power Setup</a> (QGroundControl User Guide).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>This setting corresponds to parameter(s): <a href="./../advanced_config/parameter_reference.html#BAT1_A_PER_V">BAT1_A_PER_V</a> and <a href="./../advanced_config/parameter_reference.html#BAT2_A_PER_V">BAT2_A_PER_V</a>.</p></div><h2 id="load_compensation" tabindex="-1">Voltage-based Estimation with Load Compensation <a class="header-anchor" href="#load_compensation" aria-label="Permalink to &quot;Voltage-based Estimation with Load Compensation {#load_compensation}&quot;">​</a></h2><p>When a current flows through a battery, the internal resistance causes a voltage drop, reducing the measured output voltage of the battery compared to its open-circuit (no-load) voltage. When using the <a href="#basic_settings">basic configuration</a>, the measured output voltage is what is used to estimate the available capacity, which means that the battery level will appear to fluctuate when you fly up and down, or otherwise change the load on the battery.</p><p><em>Load compensation</em> uses a measured or estimated value for the internal resistance to correct for changes under load, resulting in far less variation in the estimated capacity when flying. This is enabled by default when using a power module that provides current measurements.</p><p>To use the load compensation first set the <a href="#basic_settings">basic configuration</a>. The <em>Empty Voltage</em> (<a href="./../advanced_config/parameter_reference.html#BAT1_V_EMPTY">BATn_V_EMPTY</a>, where <code>n</code> is the battery number) should be set higher (than without compensation) because the compensated voltage gets used for the estimation (typically set a bit below the expected rest cell voltage when empty after use).</p><p>You will then need to calibrate the <a href="#current_divider">Amps per volt divider</a> in the basic settings screen (in order to get reliable current measurements).</p><p>PX4 uses current-based load compensation based on a <em>real-time estimate</em> of the internal resistance of the battery by default (real time estimates are enabled if <a href="./../advanced_config/parameter_reference.html#BAT1_R_INTERNAL">BAT1_R_INTERNAL=-1</a>). Using a real time estimate allows the compensation to adapt to changes in the internal resistance of the battery due to temperature changes during flight, as well as over time as the battery degrades.</p><p>The internal resistance can also be measured and <a href="./../advanced_config/parameters.html">set manually</a> in <a href="./../advanced_config/parameter_reference.html#BAT1_R_INTERNAL">BAT1_R_INTERNAL</a>. A positive value in this parameter will be used for the internal resistance instead of the estimated value (<code>0</code> disables load compensation altogether).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>There are LiPo chargers that can measure the internal resistance of your battery. A typical value for LiPo batteries is 5mΩ per cell but this can vary with discharge current rating, age and health of the cells.</p></div><h2 id="current_integration" tabindex="-1">Voltage-based Estimation Fused with Current Integration <a class="header-anchor" href="#current_integration" aria-label="Permalink to &quot;Voltage-based Estimation Fused with Current Integration {#current_integration}&quot;">​</a></h2><p>This method is the most accurate way to measure relative battery consumption. If set up correctly with a healthy and fresh charged battery on every boot, then the estimation quality will be comparable to that from a smart battery (and theoretically allow for accurate remaining flight time estimation).</p><p>The method evaluates the remaining battery capacity by <em>fusing</em> the voltage-based estimate for the available capacity with a current-based estimate of the charge that has been consumed. It requires hardware that can accurately measure current.</p><p>To enable this feature:</p><ol><li><p>First set up accurate voltage estimation using <a href="#load_compensation">load compensation</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Including calibrating the <a href="#current_divider">Amps per volt divider</a> setting.</p></div></li></ol><p>:::</p><ol start="2"><li><p>Set the parameter <a href="./../advanced_config/parameter_reference.html#BAT1_CAPACITY">BAT1_CAPACITY</a> to around 90% of the advertised battery capacity (usually printed on the battery label).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Do not set this value too high as this may result in a poor estimation or sudden drops in estimated capacity.</p></div></li></ol><p>:::</p><hr><p><strong>Additional information</strong></p><p>The estimate of the charge that has been consumed over time is produced by mathematically integrating the measured current (this approach provides very accurate energy consumption estimates).</p><p>At system startup PX4 first uses a voltage-based estimate to determine the initial battery charge. This estimate is then fused with the value from current integration to provide a combined better estimate. The relative value placed on each estimate in the fused result depends on the battery state. The emptier the battery gets, the more of the voltage based estimate gets fused in. This prevents deep discharge (e.g. because it was configured with the wrong capacity or the start value was wrong).</p><p>If you always start with a healthy full battery, this approach is similar to that used by a smart battery.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Current integration cannot be used on its own (without voltage-based estimation) because it has no way to determine the <em>initial</em> capacity. Voltage-estimation allows you to estimate the initial capacity and provides ongoing feedback of possible errors (e.g. if the battery is faulty, or if there is a mismatch between capacity calculated using different methods).</p></div>',71)]))}const f=a(s,[["render",l]]);export{b as __pageData,f as default};
